import{_ as a,o as i,c as r,a2 as t}from"./chunks/framework.F7eQ-ohH.js";const o="/bzygq/assets/42981579adb24158b6a2eb747099a690.DAl8-7xJ.png",s="/bzygq/assets/bdaf4593c6f94dc5afc7579be080f29b.HJw1qyqZ.png",x=JSON.parse('{"title":"08 Retain、Will、离线消息与过期机制","description":"","frontmatter":{},"headers":[],"relativePath":"Java面试问题汇总/MQTT/08 Retain、Will、离线消息与过期机制.md","filePath":"Java面试问题汇总/MQTT/08 Retain、Will、离线消息与过期机制.md","lastUpdated":1788929995000}'),l={name:"Java面试问题汇总/MQTT/08 Retain、Will、离线消息与过期机制.md"};function n(p,e,d,c,h,S){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="_08-retain、will、离线消息与过期机制" tabindex="-1">08 Retain、Will、离线消息与过期机制 <a class="header-anchor" href="#_08-retain、will、离线消息与过期机制" aria-label="Permalink to &quot;08 Retain、Will、离线消息与过期机制&quot;">​</a></h1><p>MQTT 里最容易混淆的几个能力，往往都和“客户端不在线时 Broker 到底保存什么”有关。Retained Message 保存的是某个 Topic 的最后状态，Session State 保存的是某个 ClientId 的订阅和 QoS 投递进度，Will Message 表达的是连接异常结束后的遗嘱通知，Message Expiry Interval 则给一条应用消息设置有效期。它们看起来都像“Broker 帮我留点东西”，但保存维度、触发时机和失效条件完全不同。</p><p>本章要抓住一条主线：最后状态不是离线补发，离线补发不是遗嘱通知，遗嘱通知也不是消息永久有效。只有把 retained、will、session/offline queue、message expiry 的边界讲清楚，项目里设备状态、告警事件、命令下发才不会混成一团。</p><p><img src="'+o+'" alt="images/mqtt-08-retain-will-expiry-lifecycle.png"></p><p>images/mqtt-08-retain-will-expiry-lifecycle.png</p><h2 id="一、retained-message-保存-topic-的最后状态" tabindex="-1">一、Retained Message 保存 Topic 的最后状态 <a class="header-anchor" href="#一、retained-message-保存-topic-的最后状态" aria-label="Permalink to &quot;一、Retained Message 保存 Topic 的最后状态&quot;">​</a></h2><h3 id="_1-retain-是-topic-维度的快照-不是客户端队列" tabindex="-1">1. Retain 是 Topic 维度的快照，不是客户端队列 <a class="header-anchor" href="#_1-retain-是-topic-维度的快照-不是客户端队列" aria-label="Permalink to &quot;1\\. Retain 是 Topic 维度的快照，不是客户端队列&quot;">​</a></h3><p>Retained Message 的核心语义是：发布者在 PUBLISH 报文中设置 RETAIN=1 后，Broker 会把这条消息作为该 Topic 的保留消息保存下来。以后新的非共享订阅者订阅到匹配 Topic 时，Broker 可以立即把这条“最后一条保留消息”发给它，让订阅者不必等待下一次真实上报，马上拿到当前状态。</p><p>这里的关键词是“Topic 的最后状态”。它不是按 ClientId 保存，也不是按订阅者保存，更不是保存一个历史列表。一个 Topic 通常只保留最后一条 retained 消息，新消息会覆盖旧消息；如果发布者用 retained 语义发送空载荷，常见 Broker 会把它理解为删除该 Topic 的保留消息。官方规范也明确强调，Retained Message 不构成 Server 侧 Session State，Session 结束时不能因为某个客户端会话过期就顺手删除 retained 状态。</p><p>所以项目里不能用 retained 模拟离线队列。比如设备离线期间平台连续下发三条命令，如果都发到同一个命令 Topic 且设置 retained，最后 Broker 只会留下最后一条；设备上线后看到的不是“漏掉的三条命令”，而只是该 Topic 的最新保留值。Retain 适合表达“现在是什么”，不适合表达“曾经发生过哪些事”。</p><h3 id="_2-新订阅收到-retained-不代表这条消息刚刚发生" tabindex="-1">2. 新订阅收到 retained，不代表这条消息刚刚发生 <a class="header-anchor" href="#_2-新订阅收到-retained-不代表这条消息刚刚发生" aria-label="Permalink to &quot;2\\. 新订阅收到 retained，不代表这条消息刚刚发生&quot;">​</a></h3><p>订阅者收到 retained 消息时，很容易误判为“刚刚有设备上报”。正确理解应该是：Broker 在订阅建立时补发了一份 Topic 当前快照。MQTT 5 还提供了 Retain Handling、Retain As Published 等订阅选项，用来控制订阅建立时是否发送 retained，以及转发普通消息时是否保留 RETAIN 标记；但无论选项如何变化，retained 的本质仍然是快照，而不是事件流。</p><p>工程上要给 retained 消息的 payload 设计时间戳、版本号或状态来源。比如 device/{id}/status 保留 online/offline，payload 里最好带 reportedAt 和状态来源，前端看到 retained 的 offline 才能判断这是 5 秒前 Broker 依据 Will 更新的状态，还是 3 天前遗留的旧状态。没有时间信息的 retained 快照，很容易在监控页面上制造“看似准确、实际过时”的状态。</p><h2 id="二、will-message-表达异常离线-不表达正常退出" tabindex="-1">二、Will Message 表达异常离线，不表达正常退出 <a class="header-anchor" href="#二、will-message-表达异常离线-不表达正常退出" aria-label="Permalink to &quot;二、Will Message 表达异常离线，不表达正常退出&quot;">​</a></h2><h3 id="_1-will-在-connect-时托管给-broker" tabindex="-1">1. Will 在 CONNECT 时托管给 Broker <a class="header-anchor" href="#_1-will-在-connect-时托管给-broker" aria-label="Permalink to &quot;1\\. Will 在 CONNECT 时托管给 Broker&quot;">​</a></h3><p>Will Message 是客户端在 CONNECT 时交给 Broker 的一条预置消息。只要 Will Flag 为 1，Broker 接受连接后就要把 Will Topic、Will Payload、Will QoS、Will Retain 以及 MQTT 5 的 Will Properties 关联到当前会话或网络连接上。它的目的不是让客户端主动发送一条离线消息，而是让 Broker 在客户端异常消失时，代替客户端发布一条“它非正常离线了”的通知。</p><p>典型触发条件包括：Broker 检测到 I/O 错误或网络失败、客户端超过 Keep Alive 没有通信、客户端没有先发送正常 DISCONNECT 就关闭底层连接、Broker 因协议错误关闭连接等。MQTT 3.1.1 的表达更偏向“网络连接关闭且 Will 未被删除”，MQTT 5 则进一步区分了正常断开原因码、Will Delay Interval 和 Session 结束等场景。</p><h3 id="_2-正常-disconnect-会删除-will-异常断开才发布-will" tabindex="-1">2. 正常 DISCONNECT 会删除 Will，异常断开才发布 Will <a class="header-anchor" href="#_2-正常-disconnect-会删除-will-异常断开才发布-will" aria-label="Permalink to &quot;2\\. 正常 DISCONNECT 会删除 Will，异常断开才发布 Will&quot;">​</a></h3><p>Will 最重要的边界是：正常退出不应该触发遗嘱。客户端按协议发送 DISCONNECT，MQTT 3.1.1 中 Broker 收到后会删除当前连接关联的 Will；MQTT 5 中，如果 DISCONNECT Reason Code 是 0x00 Normal disconnection，Broker 也会删除 Will。之后网络连接关闭，不再发布遗嘱消息。</p><p>这和直接断电、杀进程、容器超时退出、网络拔线完全不同。后者没有给客户端发送正常 DISCONNECT 的机会，Broker 只能把它视为异常断开，并在条件满足时发布 Will。MQTT 5 还支持 0x04 Disconnect with Will Message，表示客户端主动断开但要求发布 Will，这适合少数需要“我虽然能发出最后一个控制报文，但业务上仍要按遗嘱处理”的场景，不能和普通正常下线混用。</p><h3 id="_3-will-retain-常用于更新设备离线状态" tabindex="-1">3. Will Retain 常用于更新设备离线状态 <a class="header-anchor" href="#_3-will-retain-常用于更新设备离线状态" aria-label="Permalink to &quot;3\\. Will Retain 常用于更新设备离线状态&quot;">​</a></h3><p>Will 可以和 retained 组合使用。常见设备在线状态设计是：设备上线后向 device/{id}/status 发布 retained 的 online；连接时配置 Will Topic 仍然是 device/{id}/status，Will Payload 是 offline，并把 Will Retain 设为 1。这样设备异常掉线时，Broker 发布 retained 的 offline，后续新订阅者也能直接看到最后状态。</p><p>但这只是“状态快照更新”，不是离线消息队列。Will 只说明某个连接异常结束，不说明离线期间错过了哪些业务消息，也不保证应用已经完成资源释放。项目里还应在服务端侧结合心跳时间、最后上报时间、重连日志和设备业务状态做二次判断，避免把一次短暂网络抖动误判为真实故障。</p><h2 id="三、session-state-才是离线补发的基础" tabindex="-1">三、Session State 才是离线补发的基础 <a class="header-anchor" href="#三、session-state-才是离线补发的基础" aria-label="Permalink to &quot;三、Session State 才是离线补发的基础&quot;">​</a></h2><h3 id="_1-session-state-围绕-clientid-保存协议进度" tabindex="-1">1. Session State 围绕 ClientId 保存协议进度 <a class="header-anchor" href="#_1-session-state-围绕-clientid-保存协议进度" aria-label="Permalink to &quot;1\\. Session State 围绕 ClientId 保存协议进度&quot;">​</a></h3><p>MQTT 的离线补发依赖 Session State。Server 侧 Session State 包括会话存在本身、客户端订阅关系、已经发给客户端但尚未完成确认的 QoS 1/QoS 2 消息、等待传给客户端的 QoS 1/QoS 2 消息、可选的 QoS 0 待发送消息、未完成的 QoS 2 接收流程，以及 MQTT 5 中会话将在何时结束等信息。Client 侧也要保存自己已经发送但尚未确认的 QoS 1/QoS 2 流程，以及已收到但未完成确认的 QoS 2 流程。</p><p>这说明“离线补发”不是 Broker 随便缓存所有消息，而是某个稳定 ClientId 先前建立过可恢复会话，并且离线期间有匹配它订阅的 QoS 1/QoS 2 消息进入该会话状态。MQTT 3.1.1 用 CleanSession=0 表达持久会话；MQTT 5 用 Clean Start 和 Session Expiry Interval 拆开表达：是否清理旧会话、断开后会话保留多久。</p><h3 id="_2-离线期间-qos-1-2-才是补发主力" tabindex="-1">2. 离线期间 QoS 1/2 才是补发主力 <a class="header-anchor" href="#_2-离线期间-qos-1-2-才是补发主力" aria-label="Permalink to &quot;2\\. 离线期间 QoS 1/2 才是补发主力&quot;">​</a></h3><p>在 MQTT 3.1.1 中，如果会话使用 CleanSession=0，客户端断开后，Broker 必须把匹配该客户端已有订阅的 QoS 1 和 QoS 2 消息保存为 Session State 的一部分；QoS 0 消息可以保存，但不是强制语义。MQTT 5 继承了这个方向，并通过 Session Expiry Interval 给会话状态设置明确寿命。</p><p>因此，“订阅存在、ClientId 稳定、会话未过期、消息 QoS 足够、Broker 持久化能力足够”缺一不可。很多 Java 项目里离线消息收不到，不是 MQTT 不支持，而是客户端每次用随机 ClientId 连接、重连时 Clean Start 清掉旧会话、Session Expiry 为 0、订阅只在内存里临时存在，或者 Broker 因资源策略清理了离线队列。</p><h3 id="_3-retained-messages-do-not-form-part-of-session-state" tabindex="-1">3. Retained messages do not form part of Session state <a class="header-anchor" href="#_3-retained-messages-do-not-form-part-of-session-state" aria-label="Permalink to &quot;3\\. Retained messages do not form part of Session state&quot;">​</a></h3><p>这句话是区分 retained 和离线队列的记忆点。Retained Message 在 Broker 的 Topic 状态区，Session State 在 ClientId 的会话状态区。会话过期会清理订阅、待确认 QoS 消息和离线待发消息，但不会因为这个原因删除 Topic 上的 retained 快照；反过来，删除 retained 快照也不会清理某个客户端的离线队列。</p><p>可以用一个例子区分：订阅者 A 离线期间，传感器向 sensor/1/temp 连续发布三条 QoS 1 非 retained 数据，只要 A 的持久会话还在，这三条都可能进入 A 的离线待发队列；如果传感器发布的是 retained 状态，则 Broker 只维护该 Topic 的最后一条保留消息，新订阅者 B 会拿到最后状态，但 A 的离线队列语义并不因此成立。</p><h2 id="四、session-expiry-与-message-expiry-分别控制会话和消息寿命" tabindex="-1">四、Session Expiry 与 Message Expiry 分别控制会话和消息寿命 <a class="header-anchor" href="#四、session-expiry-与-message-expiry-分别控制会话和消息寿命" aria-label="Permalink to &quot;四、Session Expiry 与 Message Expiry 分别控制会话和消息寿命&quot;">​</a></h2><h3 id="_1-session-expiry-控制-会话状态保存多久" tabindex="-1">1. Session Expiry 控制“会话状态保存多久” <a class="header-anchor" href="#_1-session-expiry-控制-会话状态保存多久" aria-label="Permalink to &quot;1\\. Session Expiry 控制“会话状态保存多久”&quot;">​</a></h3><p>MQTT 5 的 Session Expiry Interval 是连接级属性，单位是秒。缺省或设置为 0 时，网络连接关闭后会话结束；设置为大于 0 时，连接断开后 Client 和 Server 要在该时间内保存 Session State；设置为 0xFFFFFFFF 表示会话不过期。它解决的是 Broker 资源管理问题：短暂弱网重连可以恢复会话，长期离线设备不能无限占用订阅状态和离线队列。</p><p>这也是 MQTT 5 相比 MQTT 3.1.1 更清晰的地方。Clean Start=1 只表示本次连接开始时丢弃旧会话，不等于断开后永远不保存新会话；Clean Start=0 只表示尽量恢复旧会话，也不等于会话永久存在。真正决定断开后保存多久的是 Session Expiry Interval。项目迁移时如果只把 Clean Session 机械映射成 Clean Start，很容易让离线补发行为和预期相反。</p><h3 id="_2-message-expiry-控制-这条消息还值不值得送" tabindex="-1">2. Message Expiry 控制“这条消息还值不值得送” <a class="header-anchor" href="#_2-message-expiry-控制-这条消息还值不值得送" aria-label="Permalink to &quot;2\\. Message Expiry 控制“这条消息还值不值得送”&quot;">​</a></h3><p>Message Expiry Interval 是消息级属性，表示应用消息从发布开始还能存活多少秒。如果设置了过期时间，而 Broker 在过期前还没有开始向某个匹配订阅者继续投递，就必须删除该订阅者对应的消息副本；如果没有设置，则消息本身不因该属性过期。Broker 转发等待过的消息时，还要把 Message Expiry Interval 调整为剩余有效时间，而不是原始 TTL。</p><p>这个机制的价值在于：可靠投递不等于永远有意义。设备控制命令、短时告警通知、位置快照、临时配置都有业务时效。设备离线 2 小时后再收到“打开继电器”可能比丢弃更危险；监控端收到过期位置也可能误导调度。Message Expiry 给离线消息设置了自然边界，避免 Broker 因持久会话把旧消息无限期补发出去。</p><h3 id="_3-will-message-也可以带-message-expiry" tabindex="-1">3. Will Message 也可以带 Message Expiry <a class="header-anchor" href="#_3-will-message-也可以带-message-expiry" aria-label="Permalink to &quot;3\\. Will Message 也可以带 Message Expiry&quot;">​</a></h3><p>MQTT 5 的 Will Properties 中也可以设置 Message Expiry Interval。它表示 Broker 将来发布 Will 时，这条 Will 消息作为应用消息还能存活多久。比如离线通知只希望在 5 分钟内有效，可以给 Will 设置较短的过期时间；如果 Will 同时设置了 retained，则当前 retained 消息过期后 Broker 也应丢弃它，从而避免一个很久以前的异常离线状态长期污染新订阅者的视图。</p><p>要注意，Message Expiry 不保证消息一定送达，它只定义“不应再送”的时间边界。QoS 负责确认流程，Session 负责离线期间是否有地方保存，Message Expiry 负责过期后是否丢弃。三者组合起来，才是“尽量可靠，但不过期乱送”的工程语义。</p><h2 id="五、四种机制放在同一条生命周期里看" tabindex="-1">五、四种机制放在同一条生命周期里看 <a class="header-anchor" href="#五、四种机制放在同一条生命周期里看" aria-label="Permalink to &quot;五、四种机制放在同一条生命周期里看&quot;">​</a></h2><h3 id="_1-连接建立时先决定身份、会话和遗嘱" tabindex="-1">1. 连接建立时先决定身份、会话和遗嘱 <a class="header-anchor" href="#_1-连接建立时先决定身份、会话和遗嘱" aria-label="Permalink to &quot;1\\. 连接建立时先决定身份、会话和遗嘱&quot;">​</a></h3><p>客户端连接 Broker 时，首先由 ClientId 决定会话身份。MQTT 3.1.1 用 Clean Session 决定是否复用或清理会话；MQTT 5 用 Clean Start 决定是否从旧会话开始，再用 Session Expiry Interval 决定断开后保存多久。如果客户端配置了 Will，Broker 接受连接后还要保存 Will 信息，等待异常断开或会话结束时处理。</p><p>这一步决定了后续所有行为的归属。ClientId 不稳定，离线队列就没有稳定收件人；Session Expiry 为 0，断开后就没有可恢复会话；Will 没配置或被正常 DISCONNECT 删除，异常离线通知就不会出现；retained 状态则不依赖这个客户端会话，它属于 Topic 当前值。</p><h3 id="_2-断开期间-broker-同时处理会话、遗嘱和过期" tabindex="-1">2. 断开期间 Broker 同时处理会话、遗嘱和过期 <a class="header-anchor" href="#_2-断开期间-broker-同时处理会话、遗嘱和过期" aria-label="Permalink to &quot;2\\. 断开期间 Broker 同时处理会话、遗嘱和过期&quot;">​</a></h3><p>当网络连接断开时，Broker 会先判断是否正常收到 DISCONNECT。正常断开会删除 Will；异常断开会进入 Will 发布判断。MQTT 5 如果设置了 Will Delay Interval，Broker 会等待延迟时间；如果客户端在延迟内用同一会话重新连接并继续会话，Broker 不应发布 Will；如果延迟到期或 Session 先结束，则发布 Will。</p><p>与此同时，Session State 是否保留取决于 Session Expiry Interval。离线期间进入该会话的 QoS 1/QoS 2 消息，会成为待补发消息；每条消息如果带 Message Expiry，还要在队列中随着时间减少有效期，到期后删除。Retained 快照则沿着 Topic 维度独立存在，既不会因为会话过期而消失，也不会因为客户端重连而变成离线补发列表。</p><h3 id="_3-重连后恢复的是协议状态-不是业务一致性" tabindex="-1">3. 重连后恢复的是协议状态，不是业务一致性 <a class="header-anchor" href="#_3-重连后恢复的是协议状态-不是业务一致性" aria-label="Permalink to &quot;3\\. 重连后恢复的是协议状态，不是业务一致性&quot;">​</a></h3><p>客户端重连后，如果 Broker 返回的 Session Present 表示存在旧会话，客户端可以继续使用已有订阅和未完成 QoS 流程；Broker 也会继续向它投递未过期的待发消息。但这只是协议层恢复，不等于业务层天然幂等。QoS 1 可能重复，QoS 2 也只约束 MQTT 传输流程，不替代数据库事务、命令去重、设备执行确认和业务补偿。</p><p>项目里要把 MQTT 层和业务层分开设计。离线补发可以提高“消息有机会送到”的概率，payload 里仍然要有业务唯一 ID、命令版本、告警编号、状态时间戳和执行回执。否则重连后的补发、重复投递、过期丢弃都会变成难以解释的业务故障。</p><h2 id="六、项目选型-状态、告警、命令不要混用一套策略" tabindex="-1">六、项目选型：状态、告警、命令不要混用一套策略 <a class="header-anchor" href="#六、项目选型-状态、告警、命令不要混用一套策略" aria-label="Permalink to &quot;六、项目选型：状态、告警、命令不要混用一套策略&quot;">​</a></h2><h3 id="_1-设备状态优先用-retained-表达最后状态" tabindex="-1">1. 设备状态优先用 retained 表达最后状态 <a class="header-anchor" href="#_1-设备状态优先用-retained-表达最后状态" aria-label="Permalink to &quot;1\\. 设备状态优先用 retained 表达最后状态&quot;">​</a></h3><p><img src="'+s+'" alt="images/mqtt-08-message-lifecycle-decision.png"></p><p>images/mqtt-08-message-lifecycle-decision.png</p><p>设备在线状态、开关当前值、配置快照、最近一次影子状态，通常适合 retained。它们的业务问题是“新订阅者进来后如何立刻知道当前值”，不是“离线期间每次变化都必须补齐”。设备上线发布 retained online，Will 发布 retained offline，payload 带状态时间、来源和版本，是比较清晰的状态模型。</p><p>如果状态变化本身也需要审计，就再单独发布事件 Topic 或写入数据库，不要指望 retained 保存历史。Retained 负责读当前值，事件流负责追历史，两者职责分开，前端、规则引擎和告警系统才不会围着同一个 Topic 猜语义。</p><h3 id="_2-告警更像事件流-要看是否允许过期" tabindex="-1">2. 告警更像事件流，要看是否允许过期 <a class="header-anchor" href="#_2-告警更像事件流-要看是否允许过期" aria-label="Permalink to &quot;2\\. 告警更像事件流，要看是否允许过期&quot;">​</a></h3><p>告警一般不是最后状态，而是发生过的一次事件。重要告警适合使用 QoS 1 或 QoS 2、稳定 ClientId、非零 Session Expiry，并在 payload 中带告警 ID、级别、发生时间和幂等键。这样消费端短暂离线后可以补收未处理告警，同时通过业务 ID 去重。</p><p>但告警也有时效边界。比如“温度超过阈值 10 秒”的提示，如果设备 1 小时后才补发，可能只适合进入历史记录，不适合触发实时处置。此时可以给实时通知 Topic 设置 Message Expiry，过期后不再补推；同时由服务端数据库或时序存储保存长期告警事实。不要把离线队列当成告警归档系统。</p><h3 id="_3-命令下发要慎用-retained-常配-qos-与短过期" tabindex="-1">3. 命令下发要慎用 retained，常配 QoS 与短过期 <a class="header-anchor" href="#_3-命令下发要慎用-retained-常配-qos-与短过期" aria-label="Permalink to &quot;3\\. 命令下发要慎用 retained，常配 QoS 与短过期&quot;">​</a></h3><p>命令下发最怕语义混乱。多数一次性命令不适合 retained，因为设备重连或重新订阅后可能拿到旧命令并再次执行。更稳妥的做法是：命令使用 QoS 1，设置较短 Message Expiry，payload 带命令 ID、目标设备、版本号、过期时间和执行回执 Topic；设备端执行前检查命令是否过期、是否重复、是否仍匹配当前状态。</p><p>少数“目标状态型命令”可以用 retained，例如“期望开关状态=ON”或“期望配置版本=12”。这时它表达的不是一次动作，而是期望状态，设备上线后读取并收敛到该状态。项目文档和 Topic 命名必须把 action command 与 desired state 区分开：前者是事件，通常要 QoS、过期和回执；后者是状态，才适合 retained。</p><h3 id="_4-面试和复盘时按边界回答" tabindex="-1">4. 面试和复盘时按边界回答 <a class="header-anchor" href="#_4-面试和复盘时按边界回答" aria-label="Permalink to &quot;4\\. 面试和复盘时按边界回答&quot;">​</a></h3><p>回答 MQTT 离线消息问题时，可以用一句话先定边界：retained 是 Topic 的最后快照，Session State 是 ClientId 的协议状态，Will 是异常断开的代发通知，Message Expiry 是消息有效期。然后再展开：最后状态用 retained，离线补发靠持久会话和 QoS 1/2，异常离线靠 Will，过期控制靠 Message Expiry 和 Session Expiry。</p><p>如果面试官追问“设备离线后再上线为什么没收到消息”，排查顺序也应围绕这些边界展开：ClientId 是否稳定，Clean Session/Clean Start 是否清掉旧会话，Session Expiry 是否为 0 或已经过期，订阅是否在断开前存在，消息 QoS 是否为 1/2，Message Expiry 是否已过，Broker 是否因资源策略清理了 Session State，以及你看到的那条消息到底是 retained 快照还是离线队列补发。</p>',68)])])}const _=a(l,[["render",n]]);export{x as __pageData,_ as default};
